package com.stockportfolio.model;

import com.stockportfolio.exception.InvalidInputException;
import com.stockportfolio.util.IdGenerator;

import java.time.LocalDateTime;

/**
 * A persistent, explainable rule-based recommendation generated by the Financial Advisor.
 */
public class AdvisorRecommendation {

    private final String recommendationId;
    private final String traderId;
    private final String goalId;               // nullable or empty if not tied to a specific goal
    private final LocalDateTime createdAt;
    private final RecommendationCategory category;
    private final String title;
    private final String summary;
    private final String reasoning;
    private final String assumptions;
    private RecommendationStatus status;

    public AdvisorRecommendation(String traderId, String goalId, RecommendationCategory category,
                                 String title, String summary, String reasoning, String assumptions) {
        this(IdGenerator.generate("REC"), traderId, goalId, LocalDateTime.now(), category,
                title, summary, reasoning, assumptions, RecommendationStatus.NEW);
    }

    public AdvisorRecommendation(String recommendationId, String traderId, String goalId,
                                 LocalDateTime createdAt, RecommendationCategory category,
                                 String title, String summary, String reasoning, String assumptions,
                                 RecommendationStatus status) {
        if (recommendationId == null || recommendationId.isBlank()) {
            throw new InvalidInputException("Recommendation ID cannot be empty.");
        }
        if (traderId == null || traderId.isBlank()) {
            throw new InvalidInputException("Trader ID cannot be empty.");
        }
        if (category == null) {
            throw new InvalidInputException("Recommendation category is required.");
        }
        if (title == null || title.isBlank()) {
            throw new InvalidInputException("Recommendation title cannot be empty.");
        }
        this.recommendationId = recommendationId.trim();
        this.traderId = traderId.trim();
        this.goalId = goalId != null ? goalId.trim() : "";
        this.createdAt = createdAt != null ? createdAt : LocalDateTime.now();
        this.category = category;
        this.title = title.trim();
        this.summary = summary != null ? summary.trim() : "";
        this.reasoning = reasoning != null ? reasoning.trim() : "";
        this.assumptions = assumptions != null ? assumptions.trim() : "";
        this.status = status != null ? status : RecommendationStatus.NEW;
    }

    public String getRecommendationId() { return recommendationId; }
    public String getTraderId() { return traderId; }
    public String getGoalId() { return goalId; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public RecommendationCategory getCategory() { return category; }
    public String getTitle() { return title; }
    public String getSummary() { return summary; }
    public String getReasoning() { return reasoning; }
    public String getAssumptions() { return assumptions; }
    public RecommendationStatus getStatus() { return status; }

    public void setStatus(RecommendationStatus status) {
        if (status == null) {
            throw new InvalidInputException("Status is required.");
        }
        this.status = status;
    }

    public void markReviewed() { this.status = RecommendationStatus.REVIEWED; }
    public void markAccepted() { this.status = RecommendationStatus.ACCEPTED; }
    public void markDismissed() { this.status = RecommendationStatus.DISMISSED; }
    public void markCompleted() { this.status = RecommendationStatus.COMPLETED; }

    @Override
    public String toString() {
        return "[" + status + "] " + category + " - " + title;
    }
}
